const offlineTemplates = `-- name: OfflineTemplates :many
SELECT id, form_template_id, version, definition, offline_allowed, channels, whatsapp_flow_id, retention_class_id, required_rule_keys, effective_from, status, created_at, updated_at, created_by, updated_by, row_version FROM form_template_versions WHERE status = 'published' AND offline_allowed
`

func (q *Queries) OfflineTemplates(ctx context.Context) ([]FormTemplateVersion, error) {
	rows, err := q.db.Query(ctx, offlineTemplates)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []FormTemplateVersion{}
	for rows.Next() {
		var i FormTemplateVersion
		if err := rows.Scan(
			&i.ID,
			&i.FormTemplateID,
			&i.Version,
			&i.Definition,
			&i.OfflineAllowed,
			&i.Channels,
			&i.WhatsappFlowID,
			&i.RetentionClassID,
			&i.RequiredRuleKeys,
			&i.EffectiveFrom,
			&i.Status,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.CreatedBy,
			&i.UpdatedBy,
			&i.RowVersion,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

