const tasksNeedingReminder = `-- name: TasksNeedingReminder :many
SELECT t.id, t.title, t.schedule_id, t.subject_type, t.subject_id, t.site_id, t.business_date, t.shift, t.assignee_user_id, t.assignee_role_id, t.due_at, t.priority, t.overdue, t.completed_at, t.skip_reason, t.status, t.created_at, t.updated_at, t.created_by, t.updated_by, t.row_version, t.reminded_at, s.reminder_minutes FROM tasks t JOIN schedules s ON s.id = t.schedule_id
WHERE t.status IN ('open', 'in_progress') AND t.reminded_at IS NULL AND s.reminder_minutes IS NOT NULL
  AND t.due_at - make_interval(mins => s.reminder_minutes) < now()
`

type TasksNeedingReminderRow struct {
	ID              uuid.UUID   `json:"id"`
	Title           string      `json:"title"`
	ScheduleID      *uuid.UUID  `json:"schedule_id"`
	SubjectType     *string     `json:"subject_type"`
	SubjectID       *uuid.UUID  `json:"subject_id"`
	SiteID          uuid.UUID   `json:"site_id"`
	BusinessDate    pgtype.Date `json:"business_date"`
	Shift           *string     `json:"shift"`
	AssigneeUserID  *uuid.UUID  `json:"assignee_user_id"`
	AssigneeRoleID  *uuid.UUID  `json:"assignee_role_id"`
	DueAt           *time.Time  `json:"due_at"`
	Priority        *string     `json:"priority"`
	Overdue         bool        `json:"overdue"`
	CompletedAt     *time.Time  `json:"completed_at"`
	SkipReason      *string     `json:"skip_reason"`
	Status          string      `json:"status"`
	CreatedAt       time.Time   `json:"created_at"`
	UpdatedAt       time.Time   `json:"updated_at"`
	CreatedBy       *uuid.UUID  `json:"created_by"`
	UpdatedBy       *uuid.UUID  `json:"updated_by"`
	RowVersion      int32       `json:"row_version"`
	RemindedAt      *time.Time  `json:"reminded_at"`
	ReminderMinutes *int32      `json:"reminder_minutes"`
}

func (q *Queries) TasksNeedingReminder(ctx context.Context) ([]TasksNeedingReminderRow, error) {
	rows, err := q.db.Query(ctx, tasksNeedingReminder)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TasksNeedingReminderRow{}
	for rows.Next() {
		var i TasksNeedingReminderRow
		if err := rows.Scan(
			&i.ID,
			&i.Title,
			&i.ScheduleID,
			&i.SubjectType,
			&i.SubjectID,
			&i.SiteID,
			&i.BusinessDate,
			&i.Shift,
			&i.AssigneeUserID,
			&i.AssigneeRoleID,
			&i.DueAt,
			&i.Priority,
			&i.Overdue,
			&i.CompletedAt,
			&i.SkipReason,
			&i.Status,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.CreatedBy,
			&i.UpdatedBy,
			&i.RowVersion,
			&i.RemindedAt,
			&i.ReminderMinutes,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

